public class raKovetkezo {
    public static void main()
    {
        System.out.println(raKovetkezoOsszege(""));
        System.out.println(raKovetkezoOsszege(""));
    }


    public static int raKovetkezoOsszege(String s)
    {
        int osszeg = 0;

        for (int i = 0; i < s.length()-1; ++i)
        {
            if (s.charAt(i) == s.charAt(i+1))
            {
                osszeg += s.charAt(i) - '0';
            }
        }
        
        if (s.charAt(s.length()-1) == s.charAt(0))
        {
            osszeg += s.charAt(0) - '0';
        }

        return osszeg;
    }
}
